            FfiConverterULong.allocationSize(value.`count`)
    )

    override fun write(value: UnitSubtotal, buf: ByteBuffer) {
            FfiConverterOptionalString.write(value.`unit`, buf)
            FfiConverterDouble.write(value.`total`, buf)
            FfiConverterULong.write(value.`count`, buf)
    }
}





/**
 * Errores tipados del core expuestos de forma segura hacia Kotlin vía UniFFI.
 * Nota: los campos evitan llamarse `message` porque en Kotlin colisionan con `Throwable.message`.
 */
sealed class AppException: kotlin.Exception() {
    
    class NotInitialized(
        ) : AppException() {
        override val message
            get() = ""
    }
    
    class Database(
        
        val `detail`: kotlin.String
        ) : AppException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Validation(
        
        val `detail`: kotlin.String
        ) : AppException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class NotFound(
        
        val `entity`: kotlin.String, 
        
        val `id`: kotlin.String
        ) : AppException() {
        override val message
            get() = "entity=${ `entity` }, id=${ `id` }"
    }
    
    class Sync(
        
        val `detail`: kotlin.String
        ) : AppException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Internal(
        
        val `detail`: kotlin.String
        ) : AppException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAppError : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        

        return when(buf.getInt()) {
            1 -> AppException.NotInitialized()
            2 -> AppException.Database(
                FfiConverterString.read(buf),
                )
            3 -> AppException.Validation(
                FfiConverterString.read(buf),
                )
            4 -> AppException.NotFound(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> AppException.Sync(
                FfiConverterString.read(buf),
                )
            6 -> AppException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppException): ULong {
        return when(value) {
            is AppException.NotInitialized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AppException.Database -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is AppException.Validation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is AppException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`entity`)
                + FfiConverterString.allocationSize(value.`id`)
            )
            is AppException.Sync -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is AppException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
            is AppException.NotInitialized -> {
                buf.putInt(1)
                Unit
            }
            is AppException.Database -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is AppException.Validation -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is AppException.NotFound -> {
                buf.putInt(4)
                FfiConverterString.write(value.`entity`, buf)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is AppException.Sync -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is AppException.Internal -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



